package dev.spellbookindicator;

import java.util.Arrays;
import java.util.Collection;
import static org.junit.Assert.assertEquals;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;

@RunWith(Parameterized.class)
public class SpellbookVisibilityTest
{
	@Parameterized.Parameters(name = "{0}, bankOpen={1}, visible={2}")
	public static Collection<Object[]> cases()
	{
		return Arrays.asList(new Object[][]{
			{SpellbookVisibility.OFF, false, false},
			{SpellbookVisibility.OFF, true, false},
			{SpellbookVisibility.EVERYWHERE, false, true},
			{SpellbookVisibility.EVERYWHERE, true, true},
			{SpellbookVisibility.BANK_ONLY, false, false},
			{SpellbookVisibility.BANK_ONLY, true, true},
			{SpellbookVisibility.OUTSIDE_BANK, false, true},
			{SpellbookVisibility.OUTSIDE_BANK, true, false}
		});
	}

	private final SpellbookVisibility visibility;
	private final boolean bankOpen;
	private final boolean expected;

	public SpellbookVisibilityTest(SpellbookVisibility visibility, boolean bankOpen, boolean expected)
	{
		this.visibility = visibility;
		this.bankOpen = bankOpen;
		this.expected = expected;
	}

	@Test
	public void matchesBankState()
	{
		assertEquals(expected, visibility.isVisible(bankOpen));
	}
}
